$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backup = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/fee_phase5_documents_$stamp"

function ReadProject([string]$p) {
  $f = Join-Path $root $p
  if (-not (Test-Path $f)) { throw "Missing: $p" }
  return [IO.File]::ReadAllText($f).Replace("`r`n", "`n")
}

function WriteProject([string]$p, [string]$c) {
  $f = Join-Path $root $p
  New-Item -ItemType Directory -Path (Split-Path $f -Parent) -Force | Out-Null
  [IO.File]::WriteAllText($f, $c, $utf8)
  Write-Host "Created/updated: $p" -ForegroundColor Green
}

function BackupProject([string]$p) {
  $s = Join-Path $root $p
  if (Test-Path $s) {
    $d = Join-Path $backup $p
    New-Item -ItemType Directory -Path (Split-Path $d -Parent) -Force | Out-Null
    Copy-Item $s $d -Force
  }
}

function EnsureBefore(
  [string]$content,
  [string]$marker,
  [string]$anchor,
  [string]$block
) {
  if ($content.Contains($marker)) { return $content }
  $i = $content.IndexOf($anchor)
  if ($i -lt 0) { throw "Anchor not found: $anchor" }
  return $content.Substring(0, $i) + $block + $content.Substring($i)
}

$payloads = @{
  'lib/features/fees/domain/entities/fee_document_request_entity.dart' = ''
  'lib/features/fees/domain/services/fee_document_service.dart' = ''
  'lib/features/fees/data/services/fee_document_service_impl.dart' = ''
  'lib/features/fees/presentation/bloc/fee_document_bloc.dart' = ''
  'lib/features/fees/presentation/pages/fee_challan_page.dart' = ''
}
$sl = 'lib/core/di/service_locator.dart'
$dashboard = 'lib/features/fees/presentation/pages/fee_management_dashboard_page.dart'
$collectionPage = 'lib/features/fees/presentation/pages/fee_collection_page.dart'

foreach ($p in @($sl, $dashboard, $collectionPage) + $payloads.Keys) {
  BackupProject $p
}

foreach ($item in $payloads.GetEnumerator()) {
  WriteProject $item.Key (
    [Text.Encoding]::UTF8.GetString(
      [Convert]::FromBase64String($item.Value)
    )
  )
}

# =========================================================
# Service locator
# =========================================================

$content = ReadProject $sl

$content = EnsureBefore `
  $content `
  'fee_document_service_impl.dart' `
  "import '../../features/fees/data/repositories/fee_payment_repository_impl.dart';" `
  "import '../../features/fees/data/services/fee_document_service_impl.dart';`n"

$content = EnsureBefore `
  $content `
  'fee_document_service.dart' `
  "import '../../features/fees/domain/repositories/fee_payment_repository.dart';" `
  "import '../../features/fees/domain/services/fee_document_service.dart';`n"

$content = EnsureBefore `
  $content `
  'fee_document_bloc.dart' `
  "import '../../features/fees/presentation/bloc/fee_collection_bloc.dart';" `
  "import '../../features/fees/presentation/bloc/fee_document_bloc.dart';`n"

$serviceReg = @'
  sl.registerLazySingleton<FeeDocumentService>(
    FeeDocumentServiceImpl.new,
  );

'@

$content = EnsureBefore `
  $content `
  'registerLazySingleton<FeeDocumentService>' `
  '  sl.registerLazySingleton<FeePaymentRepository>(' `
  $serviceReg

$blocReg = @'
  sl.registerFactory<FeeDocumentBloc>(
    () => FeeDocumentBloc(
      sl<FeeDocumentService>(),
    ),
  );

'@

$content = EnsureBefore `
  $content `
  'registerFactory<FeeDocumentBloc>' `
  '  sl.registerFactory<FeeCollectionBloc>(' `
  $blocReg

WriteProject $sl $content

# =========================================================
# Dashboard Challans card
# =========================================================

$content = ReadProject $dashboard

$content = EnsureBefore `
  $content `
  "import 'fee_challan_page.dart';" `
  "import 'fee_collection_page.dart';" `
  "import 'fee_challan_page.dart';`n"

if (-not $content.Contains("title: 'Fee Challans'")) {
  $reportsMarker = "      _FeeFeature(`n        title: 'Fee Reports',"
  $index = $content.IndexOf($reportsMarker)
  if ($index -lt 0) {
    throw 'Could not locate Fee Reports card.'
  }

  $card = @'
      _FeeFeature(
        title: 'Fee Challans',
        description:
            'Print and share school, parent and bank fee challan copies.',
        icon: Icons.receipt_long_outlined,
        color: const Color(0xFF5D4037),
        onTap: () {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => const FeeChallanPage(),
            ),
          );
        },
      ),
'@

  $content = $content.Insert($index, $card)
}

WriteProject $dashboard $content

# =========================================================
# Fee Collection receipt actions
# =========================================================

$content = ReadProject $collectionPage

if (-not $content.Contains("import '../../domain/entities/fee_document_request_entity.dart';")) {
  $content = $content.Replace(
    "import '../../domain/entities/fee_payment_entity.dart';",
    "import '../../domain/entities/fee_document_request_entity.dart';`nimport '../../domain/entities/fee_payment_entity.dart';"
  )
}

if (-not $content.Contains("import '../bloc/fee_document_bloc.dart';")) {
  $content = $content.Replace(
    "import '../bloc/fee_collection_bloc.dart';",
    "import '../bloc/fee_collection_bloc.dart';`nimport '../bloc/fee_document_bloc.dart';"
  )
}

# Wrap existing page provider with MultiBlocProvider.
$oldProvider = @'
    return BlocProvider<FeeCollectionBloc>(
      create: (_) => sl<FeeCollectionBloc>(),
      child: const _FeeCollectionView(),
    );
'@

$newProvider = @'
    return MultiBlocProvider(
      providers: [
        BlocProvider<FeeCollectionBloc>(
          create: (_) => sl<FeeCollectionBloc>(),
        ),
        BlocProvider<FeeDocumentBloc>(
          create: (_) => sl<FeeDocumentBloc>(),
        ),
      ],
      child: const _FeeCollectionView(),
    );
'@

if ($content.Contains($oldProvider)) {
  $content = $content.Replace($oldProvider, $newProvider)
}

# Add receipt action buttons before cancel button.
if (-not $content.Contains("tooltip: 'Print receipt'")) {
  $cancelMarker = @'
                          IconButton(
                            tooltip: 'Cancel payment',
'@
  $index = $content.IndexOf($cancelMarker)
  if ($index -lt 0) {
    throw 'Could not locate payment cancel action.'
  }

  $buttons = @'
                          IconButton(
                            tooltip: 'Print receipt',
                            onPressed: payment.status ==
                                    FeePaymentStatus.cancelled
                                ? null
                                : () => context
                                    .read<FeeDocumentBloc>()
                                    .add(
                                      PrintFeeReceipt(
                                        FeeReceiptDocumentRequest(
                                          payment: payment,
                                        ),
                                      ),
                                    ),
                            icon: const Icon(Icons.print_outlined),
                          ),
                          IconButton(
                            tooltip: 'Share receipt PDF',
                            onPressed: payment.status ==
                                    FeePaymentStatus.cancelled
                                ? null
                                : () => context
                                    .read<FeeDocumentBloc>()
                                    .add(
                                      ShareFeeReceipt(
                                        FeeReceiptDocumentRequest(
                                          payment: payment,
                                        ),
                                      ),
                                    ),
                            icon: const Icon(
                              Icons.picture_as_pdf_outlined,
                            ),
                          ),
'@

  $content = $content.Insert($index, $buttons)
}

WriteProject $collectionPage $content

# =========================================================
# Format and analyze
# =========================================================

$format = @($sl, $dashboard, $collectionPage) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan
& dart format $format
if ($LASTEXITCODE -ne 0) { throw 'dart format failed.' }

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
  throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Fee Management Phase 5 Challans and Receipts completed successfully.' -ForegroundColor Green
Write-Host "Backup: $backup" -ForegroundColor DarkGray
